	foreach ( array_filter( array_map( 'sanitize_key', explode( ',', '{{removed_product_metaboxes}}' ) ) ) as $id ) {
		foreach ( array( 'normal', 'side', 'advanced' ) as $context ) {
			remove_meta_box( $id, 'product', $context );
		}
	}
}
